macro_rules! deps {
    () => {
        State!();
        StateBuilderEmpty!();
        Config!();
        SparseSets!();
        OwnedDFA!();
        DFA!();
        StateID!();
        NFA!();
        StateMap!();
    };
}

macro_rules! Runner {
    () => {
        deps!();
        # [doc = " The actual implementation of determinization that converts an NFA to a DFA"] # [doc = " through powerset construction."] # [doc = ""] # [doc = " This determinizer roughly follows the typical powerset construction, where"] # [doc = " each DFA state is comprised of one or more NFA states. In the worst case,"] # [doc = " there is one DFA state for every possible combination of NFA states. In"] # [doc = " practice, this only happens in certain conditions, typically when there are"] # [doc = " bounded repetitions."] # [doc = ""] # [doc = " The main differences between this implementation and typical deteminization"] # [doc = " are that this implementation delays matches by one state and hackily makes"] # [doc = " look-around work. Comments below attempt to explain this."] # [doc = ""] # [doc = " The lifetime variable `'a` refers to the lifetime of the NFA or DFA,"] # [doc = " whichever is shorter."] # [derive (Debug)] struct Runner < 'a > { # [doc = " The configuration used to initialize determinization."] config : Config , # [doc = " The NFA we're converting into a DFA."] nfa : & 'a thompson :: NFA , # [doc = " The DFA we're building."] dfa : & 'a mut dense :: OwnedDFA , # [doc = " Each DFA state being built is defined as an *ordered* set of NFA"] # [doc = " states, along with some meta facts about the ordered set of NFA states."] # [doc = ""] # [doc = " This is never empty. The first state is always a dummy state such that"] # [doc = " a state id == 0 corresponds to a dead state. The second state is always"] # [doc = " the quit state."] # [doc = ""] # [doc = " Why do we have states in both a `Vec` and in a cache map below?"] # [doc = " Well, they serve two different roles based on access patterns."] # [doc = " `builder_states` is the canonical home of each state, and provides"] # [doc = " constant random access by a DFA state's ID. The cache map below, on"] # [doc = " the other hand, provides a quick way of searching for identical DFA"] # [doc = " states by using the DFA state as a key in the map. Of course, we use"] # [doc = " reference counting to avoid actually duplicating the state's data"] # [doc = " itself. (Although this has never been benchmarked.) Note that the cache"] # [doc = " map does not give us full minimization; it just lets us avoid some very"] # [doc = " obvious redundant states."] # [doc = ""] # [doc = " Note that the index into this Vec isn't quite the DFA's state ID."] # [doc = " Rather, it's just an index. To get the state ID, you have to multiply"] # [doc = " it by the DFA's stride. That's done by self.dfa.from_index. And the"] # [doc = " inverse is self.dfa.to_index."] # [doc = ""] # [doc = " Moreover, DFA states don't usually retain the IDs assigned to them"] # [doc = " by their position in this Vec. After determinization completes,"] # [doc = " states are shuffled around to support other optimizations. See the"] # [doc = " sibling 'special' module for more details on that. (The reason for"] # [doc = " mentioning this is that if you print out the DFA for debugging during"] # [doc = " determinization, and then print out the final DFA after it is fully"] # [doc = " built, then the state IDs likely won't match up.)"] builder_states : Vec < State > , # [doc = " A cache of DFA states that already exist and can be easily looked up"] # [doc = " via ordered sets of NFA states."] # [doc = ""] # [doc = " See `builder_states` docs for why we store states in two different"] # [doc = " ways."] cache : StateMap , # [doc = " The memory usage, in bytes, used by builder_states and cache. We track"] # [doc = " this as new states are added since states use a variable amount of"] # [doc = " heap. Tracking this as we add states makes it possible to compute the"] # [doc = " total amount of memory used by the determinizer in constant time."] memory_usage_state : usize , # [doc = " A pair of sparse sets for tracking ordered sets of NFA state IDs."] # [doc = " These are reused throughout determinization. A bounded sparse set"] # [doc = " gives us constant time insertion, membership testing and clearing."] sparses : SparseSets , # [doc = " Scratch space for a stack of NFA states to visit, for depth first"] # [doc = " visiting without recursion."] stack : Vec < StateID > , # [doc = " Scratch space for storing an ordered sequence of NFA states, for"] # [doc = " amortizing allocation. This is principally useful for when we avoid"] # [doc = " adding a new DFA state since it already exists. In order to detect this"] # [doc = " case though, we still need an ordered set of NFA state IDs. So we use"] # [doc = " this space to stage that ordered set before we know whether we need to"] # [doc = " create a new DFA state or not."] scratch_state_builder : StateBuilderEmpty , }
    };
}

Runner!()